#[derive(Debug, Eq, Serialize, Deserialize, PartialEq, Clone)]
pub struct JSONCommandState {
    pub act_unknown: Vec<JSONActUnknown>,
    pub act_copy_path: Vec<JSONActCopyPath>,
    pub act_file_transfer: Vec<JSONActFileTransfer>,
    pub act_realise: Vec<JSONActRealise>,
    pub act_copy_paths: Vec<JSONActCopyPaths>,
    pub act_builds: Vec<JSONActBuilds>,
    pub act_build: Vec<JSONActBuild>,
    pub act_optimise_store: Vec<JSONActOptimiseStore>,
    pub act_verify_paths: Vec<JSONActVerifyPaths>,
    pub act_substitute: Vec<JSONActSubstitute>,
    pub act_query_path_info: Vec<JSONActQueryPathInfo>,
    pub act_post_build_hook: Vec<JSONActPostBuildHook>,
    pub act_build_waiting: Vec<JSONActBuildWaiting>,
    pub start: SystemTime,
    pub end: SystemTime,
    pub required_derivations: HashSet<String>,
}

impl CommandState {
    pub fn new() -> CommandState {
        CommandState {
            activity: HashMap::new(),
            required_derivations: HashSet::new(),
            running: HashSet::new(),
            completed: HashSet::new(),
            failed: HashSet::new(),
            start: SystemTime::now(),
            end: None, // Initialize end as None by default
        }
    }
    pub fn to_json(state: CommandState) -> JSONCommandState {
        let mut act_unknown = Vec::new();
        let mut act_copy_path = Vec::new();
        let mut act_file_transfer = Vec::new();
        let mut act_realise = Vec::new();
        let mut act_copy_paths = Vec::new();
        let mut act_builds = Vec::new();
        let mut act_build = Vec::new();
        let mut act_optimise_store = Vec::new();
        let mut act_verify_paths = Vec::new();
        let mut act_substitute = Vec::new();
        let mut act_query_path_info = Vec::new();
        let mut act_post_build_hook = Vec::new();
        let mut act_build_waiting = Vec::new();
        for (_, act) in state.activity {
            let start = act.start;
            let end = act.end.unwrap_or(SystemTime::now());
            match act.activity {
                Activity::ActCopyPath(package_name, store_path, from, to) => {
                    act_copy_path.push(JSONActCopyPath {
                        start,
                        end,
                        package_name,
                        store_path,
                        from,
                        to,
                    })
                }
                Activity::ActBuild(package_name, store_path, host, _, _) => {
                    act_build.push(JSONActBuild {
                        start,
                        end,
                        package_name,
                        store_path,
                        host,
                    })
                }
                Activity::ActFileTransfer(file) => {
                    act_file_transfer.push(JSONActFileTransfer { start, end, file })
                }
                Activity::ActSubstitute(package_name, store_path, from) => {
                    act_substitute.push(JSONActSubstitute {
                        start,
                        end,
                        package_name,
                        store_path,
                        from,
                    })
                }
                Activity::ActQueryPathInfo(package_name, store_path, from) => act_query_path_info
                    .push(JSONActQueryPathInfo {
                        start,
                        end,
                        package_name,
                        store_path,
                        from,
                    }),
                Activity::ActPostBuildHook(store_path) => {
                    act_post_build_hook.push(JSONActPostBuildHook {
                        store_path: store_path,
                        start,
                        end,
                    })
                }
                Activity::ActRealise => act_realise.push(JSONActRealise { start, end }),
                Activity::ActCopyPaths => act_copy_paths.push(JSONActCopyPaths { start, end }),
                Activity::ActBuilds => act_builds.push(JSONActBuilds { start, end }),
                Activity::ActUnknown => act_unknown.push(JSONActUnknown { start, end }),
                Activity::ActOptimiseStore => {
                    act_optimise_store.push(JSONActOptimiseStore { start, end })
                }
                Activity::ActVerifyPaths => {
                    act_verify_paths.push(JSONActVerifyPaths { start, end })
                }
                Activity::ActBuildWaiting => {
                    act_build_waiting.push(JSONActBuildWaiting { start, end })
                }
                Activity::ActFetchTree => {}
            }
        }

        JSONCommandState {
            act_unknown,
            act_copy_path,
            act_file_transfer,
            act_realise,
            act_copy_paths,
            act_builds,
            act_build,
            act_optimise_store,
            act_verify_paths,
            act_substitute,
            act_query_path_info,
            act_post_build_hook,
            act_build_waiting,
            start: state.start,
            end: state.end.unwrap(),
            required_derivations: state.required_derivations,
        }
    }
}

use std::thread;

use super::{helpers::append_log_to_file, types::*};
use serde_json::{self, Value};

fn get_package_from_drv(store_path: String) -> String {
    match store_path.split_once('-') {
        Some((_, xs)) => xs
            .to_owned()
            .replace(".drv", "")
            .replace("\\\"", "")
            .replace('\"', ""),
        None => store_path,
    }
}

fn str_to_verbosity(lvl: i64) -> Verbosity {
    match lvl {
        0 => Verbosity::Error,
        1 => Verbosity::Warn,
        2 => Verbosity::Notice,
        3 => Verbosity::Info,
        4 => Verbosity::Talkative,
        5 => Verbosity::Chatty,
        6 => Verbosity::Debug,
        7 => Verbosity::Vomit,
        _ => Verbosity::Info,
    }
}

fn number_to_activity_type(number: i64) -> ActivityType {
    match number {
        0 => ActivityType::ActUnknownType,
        100 => ActivityType::ActCopyPathType,
        101 => ActivityType::ActFileTransferType,
        102 => ActivityType::ActRealiseType,
        103 => ActivityType::ActCopyPathsType,
        104 => ActivityType::ActBuildsType,
        105 => ActivityType::ActBuildType,
        106 => ActivityType::ActOptimiseStoreType,
        107 => ActivityType::ActVerifyPathsType,
        108 => ActivityType::ActSubstituteType,
        109 => ActivityType::ActQueryPathInfoType,
        110 => ActivityType::ActPostBuildHookType,
        111 => ActivityType::ActBuildWaitingType,
        112 => ActivityType::ActFetchTreeType,
        _ => ActivityType::ActUnknownType, // Default case for unknown values
    }
}

fn str_to_activity_result(activity_result: i64, fields: Value) -> ActivityResult {
    match activity_result {
        100 => {
            let fields_i64: Vec<i64> = serde_json::from_value(fields).unwrap();
            ActivityResult::FileLinked(fields_i64[0], fields_i64[1])
        }
        101 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            ActivityResult::BuildLogLine(fields_str[0].to_owned())
        }
        102 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            ActivityResult::UntrustedPath(fields_str[0].to_owned())
        }
        103 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            ActivityResult::CorruptedPath(fields_str[0].to_owned())
        }
        104 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            ActivityResult::SetPhase(fields_str[0].to_owned())
        }
        105 => {
            let fields_i64: Vec<i64> = serde_json::from_value(fields).unwrap();
            ActivityResult::Progress(ActivityProgress {
                done: fields_i64[0],
                expected: fields_i64[1],
                running: fields_i64[2],
                failed: fields_i64[3],
            })
        }
        106 => {
            let fields_i64: Vec<i64> = serde_json::from_value(fields).unwrap();
            ActivityResult::SetExpected(number_to_activity_type(fields_i64[0]), fields_i64[1])
        }
        107 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            ActivityResult::PostBuildLogLine(fields_str[0].to_owned())
        }
        x => panic!("unable to parse str_to_activity_result: {}", x),
    }
}

fn str_to_activity(activity: i64, fields: Value) -> Activity {
    match activity {
        // actUnknown = 0,
        0 => Activity::ActUnknown,
        // actCopyPath = 100,
        100 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            let store_path = fields_str[0].to_owned();
            let from = fields_str[1].to_owned();
            let to = fields_str[2].to_owned();
            let package_name = get_package_from_drv(store_path.to_owned());
            Activity::ActCopyPath(package_name, store_path, from, to)
        }
        // actFileTransfer = 101,
        101 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            let nar = fields_str[0].to_owned();
            Activity::ActFileTransfer(nar)
        }
        // actRealise = 102,
        102 => Activity::ActRealise,
        // actCopyPaths = 103,
        103 => Activity::ActCopyPaths,
        // actBuilds = 104,
        104 => Activity::ActBuilds,
        // actBuild = 105,
        105 => {
            let fields_str: Vec<Value> = serde_json::from_value(fields).unwrap();
            let path: String = serde_json::from_value(fields_str[0].to_owned()).unwrap();
            let host: String = serde_json::from_value(fields_str[1].to_owned()).unwrap();
            let package_name = get_package_from_drv(path.clone());
            Activity::ActBuild(package_name, path, host, 1, 1)
        }
        // actOptimiseStore = 106,
        106 => Activity::ActOptimiseStore,
        // actVerifyPaths = 107,
        107 => Activity::ActVerifyPaths,
        // actSubstitute = 108,
        108 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            let path = fields_str[0].to_owned();
            let host = fields_str[1].to_owned();
            let package_name = get_package_from_drv(path.clone());
            Activity::ActSubstitute(package_name, path, host)
        }
        // actQueryPathInfo = 109,
        109 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            let path = fields_str[0].to_owned();
            let host = fields_str[1].to_owned();
            let package_name = get_package_from_drv(path.clone());
            Activity::ActQueryPathInfo(package_name, path, host)
        }
        // actPostBuildHook = 110,
        110 => {
            let fields_str: Vec<String> = serde_json::from_value(fields).unwrap();
            Activity::ActPostBuildHook(fields_str[0].to_owned())
        }
        // actBuildWaiting = 111,
        111 => Activity::ActBuildWaiting,
        // actFetchTree = 112,
        112 => {
            Activity::ActFetchTree
        }
        _ => panic!("Invalid Activity"),
    }
}

pub fn parse(line: String) -> (Option<JSONMessage>, i64) {
    let opt_res: Result<serde_json::Value, _> = serde_json::from_str(&line.replace("@nix ", ""));
    match opt_res {
        Ok(res) => {
            let action = res.get("action").unwrap().as_str();
            let d_fields = Value::Array([].to_vec());
            let mut id = -1;
            let msg = match action {
                Some("start") => {
                    id = serde_json::from_value(res.get("id").unwrap().to_owned()).unwrap();
                    let fields = match res.get("fields") {
                        Some(v) => v,
                        None => &d_fields,
                    };
                    let level = str_to_verbosity(
                        serde_json::from_value(res.get("level").unwrap().to_owned()).unwrap(),
                    );
                    let text: String =
                        serde_json::from_value(res.get("text").unwrap().to_owned()).unwrap();
                    let text_log: String = text.clone();
                    let _type =
                        serde_json::from_value(res.get("type").unwrap().to_owned()).unwrap();
                    let activity = str_to_activity(_type, fields.clone());

                    //write to log file
                    thread::spawn(move || {
                        let log_file = "id_".to_owned() + &(id.clone().to_string());
                        append_log_to_file(log_file, text_log.to_owned());
                    });

                    Some(JSONMessage::Start(StartAction {
                        id,
                        level,
                        activity,
                        text: text.to_owned(),
                    }))
                }
                Some("stop") => {
                    id = serde_json::from_value(res.get("id").unwrap().to_owned()).unwrap();
                    thread::spawn(move || {
                        let log_file = "id_".to_owned() + &(id.clone().to_string());
                        append_log_to_file(log_file, String::from("done"));
                    });
                    Some(JSONMessage::Stop(StopAction { id }))
                }
                Some("result") => {
                    id = serde_json::from_value(res.get("id").unwrap().to_owned()).unwrap();
                    let fields = res.get("fields").unwrap();
                    let activity: ActivityResult = str_to_activity_result(
                        serde_json::from_value(res.get("type").unwrap().to_owned()).unwrap(),
                        fields.clone(),
                    );
                    let text: Option<String> = match activity.clone() {
                        ActivityResult::BuildLogLine(msg) => Some(msg),
                        ActivityResult::UntrustedPath(msg) => Some(msg),
                        ActivityResult::CorruptedPath(msg) => Some(msg),
                        ActivityResult::SetPhase(msg) => Some(msg),
                        _ => None, // ActivityResult::Progress(msg) => Some(),
                                   // ActivityResult::FileLinked(_, _) => Some(String::from("")),
                                   // ActivityResult::SetExpected(_, _) => Some(String::from("")),
                                   // ActivityResult::PostBuildLogLine(_) => Some(String::from("")),
                    };
                    match text {
                        Some(msg) => {
                            thread::spawn(move || {
                                let log_file = "id_".to_owned() + &(id.clone().to_string());
                                append_log_to_file(log_file, msg.clone());
                            });
                        }
                        None => (),
                    }
                    Some(JSONMessage::Result(ResultAction {
                        id,
                        result: activity,
                    }))
                }
                Some("msg") => {
                    let level = str_to_verbosity(
                        serde_json::from_value(res.get("level").unwrap().to_owned()).unwrap(),
                    );
                    let msg: String =
                        serde_json::from_value(res.get("msg").unwrap().clone()).unwrap();
                    let msg_log: String =
                        serde_json::from_value(res.get("msg").unwrap().clone()).unwrap();

                    //write to log file
                    thread::spawn(move || {
                        let log_file = "id_".to_owned() + &(id.clone().to_string());
                        append_log_to_file(log_file, msg_log.to_owned());
                    });

                    Some(JSONMessage::Message(MessageAction {
                        level,
                        msg: msg.to_owned(),
                    }))
                }
                Some(l) => {
                    println!("Missed to handle: {:#?} , json: {:#?}", l, res);
                    None
                }
                None => None,
            };
            (msg, id)
        }
        Err(err) => {
            log::error!("Failed to parse: {} -> {}", line, err);
            (None, -1)
        }
    }
}

use yansi::Paint;

use crate::nix_tracker::types::{ActivityState, CommandState};

use super::types::{JSONMessage, Verbosity};
use std::time::SystemTime;

pub fn process_log(
    id: i64,
    opt_msg: Option<JSONMessage>,
    state: &mut CommandState,
) -> &mut CommandState {
    match opt_msg {
        Some(JSONMessage::Start(msg)) => {
            let (id, _level, _text, activity) = (msg.id, msg.level, msg.text, msg.activity);
            match activity {
                super::types::Activity::ActCopyPath(package_name, store_path, from, to) => {
                    let now = SystemTime::now();
                    log::trace!(
                        "id: {} -> activity: {} -> time {:?}",
                        id,
                        "ActCopyPath",
                        now
                    );
                    let new_activity_state = ActivityState {
                        activity: super::types::Activity::ActCopyPath(
                            package_name.clone(),
                            store_path.clone(),
                            from,
                            to,
                        ),
                        start: now,
                        end: None,
                        phase: None,
                        progress: None,
                        package_name: Some(package_name),
                    };
                    state.activity.insert(id, new_activity_state);
                    state.required_derivations.insert(store_path.clone());
                }
                super::types::Activity::ActFileTransfer(url) => {
                    let now = SystemTime::now();
                    log::trace!(
                        "id: {} -> activity: {} -> time {:?}",
                        id,
                        "ActFileTransfer",
                        now
                    );
                    let new_activity_state = ActivityState {
                        activity: super::types::Activity::ActFileTransfer(url.clone()),
                        start: now,
                        end: None,
                        phase: None,
                        progress: None,
                        package_name: None,
                    };
                    state.activity.insert(id, new_activity_state);
                }
                super::types::Activity::ActSubstitute(package_name, store_path, from) => {
                    let now = SystemTime::now();
                    log::trace!(
                        "id: {} -> activity: {} -> time {:?}",
                        id,
                        "ActSubstitute",
                        now
                    );
                    let new_activity_state = ActivityState {
                        activity: super::types::Activity::ActSubstitute(
                            package_name.clone(),
                            store_path.clone(),
                            from,
                        ),
                        start: now,
                        end: None,
                        phase: None,
                        progress: None,
                        package_name: Some(package_name),
                    };
                    state.activity.insert(id, new_activity_state);
                    state.required_derivations.insert(store_path.clone());
                }
                super::types::Activity::ActQueryPathInfo(package_name, store_path, from) => {
                    let now = SystemTime::now();
                    log::trace!(
                        "id: {} -> activity: {} -> time {:?}",
                        id,
                        "ActQueryPathInfo",
                        now
                    );
                    let new_activity_state = ActivityState {
                        activity: super::types::Activity::ActSubstitute(
                            package_name.clone(),
                            store_path.clone(),
                            from,
                        ),
                        start: now,
                        end: None,
                        phase: None,
                        progress: None,
                        package_name: Some(package_name),
                    };
                    state.activity.insert(id, new_activity_state);
                    state.required_derivations.insert(store_path.clone());
                }
                super::types::Activity::ActPostBuildHook(store_path) => {
                    let now = SystemTime::now();
                    log::trace!(
                        "id: {} -> activity: {} -> time {:?}",
                        id,
                        "ActPostBuildHook",
                        now
                    );
                    let new_activity_state = ActivityState {
                        activity: super::types::Activity::ActPostBuildHook(store_path.clone()),
                        start: now,
                        end: None,
                        phase: None,
                        progress: None,
                        package_name: None,
                    };
                    state.activity.insert(id, new_activity_state);
                    state.required_derivations.insert(store_path.clone());
                }
                super::types::Activity::ActBuild(package_name, store_path, host, _, _) => {
                    let now = SystemTime::now();
                    log::trace!("id: {} -> activity: {} -> time {:?}", id, "ActBuild", now);
                    let new_activity_state = ActivityState {
                        activity: super::types::Activity::ActBuild(
                            package_name.clone(),
                            store_path.clone(),
                            host,
                            1,
                            1,
                        ),
                        start: now,
                        end: None,
                        phase: None,
                        progress: None,
                        package_name: Some(package_name),
                    };
                    state.activity.insert(id, new_activity_state);
                    state.required_derivations.insert(store_path.clone());
                }
                act => {
                    let now = SystemTime::now();
                    let new_activity_state = ActivityState {
                        activity: act,
                        start: now,
                        end: None,
                        phase: None,
                        progress: None,
                        package_name: None,
                    };
                    state.activity.insert(id, new_activity_state);
                } // super::types::Activity::ActCopyPaths => todo!()
                  // super::types::Activity::ActBuilds => => todo!()
                  // super::types::Activity::ActOptimiseStore => todo!(),
                  // super::types::Activity::ActVerifyPaths => todo!(),
                  // super::types::Activity::ActBuildWaiting => todo!(),
                  // super::types::Activity::ActUnknown => todo!()
            }
        }
        Some(JSONMessage::Stop(act)) => {
            let end = SystemTime::now();
            let id = &act.id;
            match state.activity.get(id) {
                Some(v) => {
                    let v_updated = ActivityState {
                        activity: v.activity.clone(),
                        start: v.start,
                        end: Some(end),
                        phase: v.phase.clone(),
                        progress: v.progress,
                        package_name: v.package_name.clone(),
                    };
                    state.activity.insert(*id, v_updated);
                }
                None => {
                    log::trace!("id not found in the HM: {} -> Stop", id);
                }
            }
        }
        Some(JSONMessage::Result(act)) => match act.result {
            super::types::ActivityResult::SetPhase(phase) => {
                let id = &act.id;
                match state.activity.get(id) {
                    Some(v) => {
                        let v_updated = ActivityState {
                            activity: v.activity.clone(),
                            start: v.start,
                            end: v.end,
                            phase: Some(phase),
                            progress: v.progress,
                            package_name: v.package_name.clone(),
                        };
                        state.activity.insert(*id, v_updated);
                    }
                    None => {
                        log::trace!("id not found in the HM Result: {} -> {}", id, phase);
                    }
                }
            }
            super::types::ActivityResult::Progress(progress) => {
                let id = &act.id;
                match state.activity.get(id) {
                    Some(v) => {
                        let v_updated = ActivityState {
                            activity: v.activity.clone(),
                            start: v.start,
                            end: v.end,
                            phase: v.phase.to_owned(),
                            progress: Some(progress),
                            package_name: v.package_name.clone(),
                        };
                        state.activity.insert(*id, v_updated);
                    }
                    None => {
                        log::trace!("id not found in the HM Progress: {} -> {:#?}", id, progress);
                    }
                }
            }
            super::types::ActivityResult::BuildLogLine(log) => {
                let data_about_build = &state.activity.get(&id).unwrap().package_name;
                let utf8_string = strip_ansi_escapes::strip_str(log);
                let mut pkg_name = match data_about_build {
                    Some(p) => p.to_string(),
                    None => "".to_string(),
                };
                if !pkg_name.is_empty() {
                    pkg_name.push('>');
                }
                if utf8_string.contains("warning") {
                    log::warn!("{} {}", Paint::green(&pkg_name), utf8_string);
                } else if utf8_string.contains("error") {
                    log::error!("{} {}", Paint::green(&pkg_name), utf8_string);
                } else {
                    log::info!("{} {}", Paint::green(&pkg_name), utf8_string);
                }
            }
            super::types::ActivityResult::PostBuildLogLine(log) => {
                log::trace!("PostBuildLogLine: {}", log);
            }
            super::types::ActivityResult::UntrustedPath(log) => {
                log::warn!("PostBuildLogLine: {}", log);
            }
            super::types::ActivityResult::CorruptedPath(log) => {
                log::error!("CorruptedPath: {}", log);
            }
            _ => {} // super::types::ActivityResult::FileLinked(a, b) => {
                    //     log::error!("FileLinked: {} && {}", a, b);
                    // }
                    // super::types::ActivityResult::SetExpected(activity, i) => {
                    //     log::trace!("SetExpected: {:?} && {}", activity, i);
                    // }
        },
        Some(JSONMessage::Message(act)) => {
            let no_package_name = &"".to_string();
            let pkg_name: &mut String = &mut match state.activity.get(&id) {
                Some(v) => match &v.package_name {
                    Some(pkg_name) => pkg_name.to_string(),
                    None => no_package_name.to_string(),
                },
                None => no_package_name.to_string(),
            };
            let (lvl, log) = (act.level.to_owned(), act.msg.to_owned());
            let utf8_string = strip_ansi_escapes::strip_str(log);
            if pkg_name != no_package_name {
                pkg_name.push('>');
                match lvl {
                    Verbosity::Error => log::error!("{} {}", Paint::green(pkg_name), utf8_string),
                    Verbosity::Warn => log::warn!("{} {}", Paint::green(pkg_name), utf8_string),
                    Verbosity::Notice => log::warn!("{} {}", Paint::green(pkg_name), utf8_string),
                    Verbosity::Info => log::info!("{} {}", Paint::green(pkg_name), utf8_string),
                    _ => log::trace!("{} {}", Paint::green(pkg_name), utf8_string),
                };
            } else {
                match lvl {
                    Verbosity::Error => log::error!("{}", utf8_string),
                    Verbosity::Warn => log::warn!("{}", utf8_string),
                    Verbosity::Notice => log::warn!("{}", utf8_string),
                    Verbosity::Info => log::info!("{}", utf8_string),
                    _ => log::trace!("{}", utf8_string),
                };
            }
        }
        None => {}
    }
    state
}
